            if (intent?.action == ACTION_VOLUME_CHANGED) {
                val streamType =
                    intent.getIntExtra(EXTRA_VOLUME_STREAM_TYPE, -1)
                if (streamType != AudioManager.STREAM_RING) {
                    return
                }
                if (callkitSoundPlayerManager?.isPlaying == true) {
                    callkitSoundPlayerManager.stop()
                }
            }
        }
    }
