  State<CallScreen> createState() => _CallScreenState();
}

class _CallScreenState extends State<CallScreen> {
  bool muted = false;
  bool speaker = false;
  bool connected = false;
  bool? remoteOnline;
  int seconds = 0;

  Timer? _timer;
  bool _closing = false;

  @override
  void initState() {
    super.initState();

    final manager = RtcCallManager.instance;
    remoteOnline = manager.remoteOnline;

    manager.onRemoteAvailabilityChanged = (online) {
      if (!mounted) return;
      setState(() => remoteOnline = online);
    };

    manager.onConnected = () {
      if (!mounted) return;

      setState(() {
        connected = true;
      });

      _startTimer();
    };

    manager.onDisconnected = () {
      if (_closing) return;

      _closing = true;

      if (!mounted) return;

      _timer?.cancel();

      if (Navigator.of(context).canPop()) {
        Navigator.of(context).pop();
      }
    };

    if (manager.inCall) {
      connected = true;
      _startTimer();
    }
  }

  void _startTimer() {
    if (_timer != null) return;

    _timer = Timer.periodic(const Duration(seconds: 1), (_) {
      if (!mounted || !connected) return;

      setState(() {
        seconds++;
      });
    });
  }

  String get durationText {
    final minutes = seconds ~/ 60;
    final remainingSeconds = seconds % 60;

    return '${minutes.toString().padLeft(2, '0')}:'
        '${remainingSeconds.toString().padLeft(2, '0')}';
  }

  Future<void> toggleMute() async {
    final value = !muted;

    await RtcCallManager.instance.mute(value);

    if (!mounted) return;

    setState(() {
      muted = value;
    });
  }

  Future<void> toggleSpeaker() async {
    final value = !speaker;

    await RtcCallManager.instance.setSpeaker(value);

    if (!mounted) return;

    setState(() {
      speaker = value;
    });
  }

  Future<void> endCall() async {
    if (_closing) return;

    _closing = true;

    await RtcCallManager.instance.hangup();

