package com.example.mobile

import android.content.Context
import android.content.Intent
import android.os.Bundle
import android.telecom.CallAudioState
import android.telecom.Connection
import android.telecom.ConnectionRequest
import android.telecom.ConnectionService
import android.telecom.DisconnectCause
import android.telecom.PhoneAccountHandle
import android.telecom.TelecomManager
import java.util.UUID
import java.util.concurrent.ConcurrentHashMap

/** The application's single, system-managed Telecom ConnectionService. */
class CallConnectionService : ConnectionService() {
    companion object {
        const val ACTION_CALL_ACCEPT = "com.example.mobile.CN_CALL_ACCEPT"
        const val ACTION_CALL_REJECT = "com.example.mobile.CN_CALL_REJECT"
        const val ACTION_CALL_DISCONNECT = "com.example.mobile.CN_CALL_DISCONNECT"
        const val ACTION_CALL_OUTGOING = "com.example.mobile.CN_CALL_OUTGOING"
        const val ACTION_CALL_MUTE_CHANGED = "com.example.mobile.CN_CALL_MUTE_CHANGED"

        const val EXTRA_CALL_ID = "call_id"
        const val EXTRA_CALLER_ID = "caller_id"
        const val EXTRA_CALLER_NAME = "caller_name"

        private val connections = ConcurrentHashMap<String, Connection>()
        private val peers = ConcurrentHashMap<String, String>()
        @Volatile private var appContext: Context? = null

        fun disconnectCall(callId: String, notifyFlutter: Boolean = true) {
            val id = callId.trim()
            val connection = connections.remove(id) ?: return
            val peerId = peers.remove(id).orEmpty()
            connection.setDisconnected(DisconnectCause(DisconnectCause.REMOTE))
            connection.destroy()
            appContext?.let { context ->
                stopForegroundIfIdle(context)
                if (notifyFlutter && peerId.isNotEmpty()) {
                    context.sendBroadcast(Intent(context, TelecomCallActionReceiver::class.java).apply {
                        action = ACTION_CALL_DISCONNECT
                        putExtra(EXTRA_CALL_ID, id)
                        putExtra(EXTRA_CALLER_ID, peerId)
                    })
                }
            }
        }

        fun activateCall(callId: String): Boolean {
            val id = callId.trim()
            val connection = connections[id] ?: return false

            println("[CN CALL][TELECOM ACTIVE] call_id=$id")

            appContext?.let { context ->
                CallForegroundService.start(
                    context,
                    id,
                    peers[id].orEmpty(),
                    "CN CALL",
                )
                println("[CN CALL][FGS START] call_id=$id")
            }

            connection.setRingbackRequested(false)
            connection.setActive()
            return true
        }

        fun failCall(callId: String): Boolean {
            val id = callId.trim()
            val connection = connections.remove(id) ?: return false
            peers.remove(id)
            connection.setRingbackRequested(false)
            connection.setDisconnected(DisconnectCause(DisconnectCause.ERROR))
            connection.destroy()
            appContext?.let(::stopForegroundIfIdle)
            return true
        }

        private fun stopForegroundIfIdle(context: Context) {
            if (connections.isEmpty()) CallForegroundService.stop(context)
        }
    }

    override fun onCreate() {
        super.onCreate()
        appContext = applicationContext
    }

    override fun onCreateIncomingConnection(
        connectionManagerPhoneAccount: PhoneAccountHandle,
        request: ConnectionRequest
    ): Connection {
        val extras: Bundle = request.extras ?: Bundle.EMPTY
        val callId = extras.getString(EXTRA_CALL_ID).orEmpty().trim()
        val callerId = (request.address?.schemeSpecificPart
            ?: extras.getString(EXTRA_CALLER_ID)).orEmpty().trim()
        val callerName = extras.getString(EXTRA_CALLER_NAME).orEmpty().trim()
            .ifEmpty { callerId.ifEmpty { "CN CALL" } }

        if (callId.isEmpty() || callerId.isEmpty()) {
            return Connection.createFailedConnection(
                DisconnectCause(DisconnectCause.ERROR, "Missing incoming call identity")
            )
        }

        println("CN CALL Telecom: creating incoming callId=$callId callerId=$callerId")
        return createConnection(callId, callerId, callerName, request.address).also {
            it.setRinging()
        }
    }

    override fun onCreateOutgoingConnection(
        connectionManagerPhoneAccount: PhoneAccountHandle,
        request: ConnectionRequest
    ): Connection {
        val targetId = request.address?.schemeSpecificPart.orEmpty().trim()
        if (targetId.isEmpty()) {
            return Connection.createFailedConnection(
                DisconnectCause(DisconnectCause.ERROR, "Missing outgoing target")
            )
        }

        // A dialer-originated request has no server id; create one before
        // handing the call to Flutter and LiveKit.
        val callId = UUID.randomUUID().toString()
        println("CN CALL Telecom: creating outgoing callId=$callId targetId=$targetId")
        return createConnection(callId, targetId, targetId, request.address).also {
            it.setDialing()
            // Managed Telecom/InCallUI supplies the real network ringback.
            it.setRingbackRequested(false)
            sendCallAction(ACTION_CALL_OUTGOING, callId, targetId)
        }
    }

    override fun onCreateIncomingConnectionFailed(
        connectionManagerPhoneAccount: PhoneAccountHandle,
        request: ConnectionRequest
    ) {
        super.onCreateIncomingConnectionFailed(connectionManagerPhoneAccount, request)
        println("CN CALL Telecom: incoming connection denied by Telecom")
        val extras = request.extras ?: Bundle.EMPTY
        val callId = extras.getString(EXTRA_CALL_ID).orEmpty().trim()
        val peerId = (request.address?.schemeSpecificPart
            ?: extras.getString(EXTRA_CALLER_ID)).orEmpty().trim()
        // Telecom rejected the UI before a Connection existed. Tell the same
        // Flutter lifecycle to reject the server call; otherwise the caller
        // would remain ringing until timeout.
        if (callId.isNotEmpty() && peerId.isNotEmpty()) {
            sendCallAction(ACTION_CALL_REJECT, callId, peerId)
        }
    }

    override fun onCreateOutgoingConnectionFailed(
        connectionManagerPhoneAccount: PhoneAccountHandle,
        request: ConnectionRequest
    ) {
        super.onCreateOutgoingConnectionFailed(connectionManagerPhoneAccount, request)
        println("CN CALL Telecom: outgoing connection denied by Telecom")
    }

    private fun createConnection(
        callId: String,
        peerId: String,
        displayName: String,
        address: android.net.Uri?,
    ): Connection {
        val connection = object : Connection() {
            override fun onAnswer() {
                super.onAnswer()
                // Do not advertise ACTIVE until Flutter has connected LiveKit,
                // published the microphone and explicitly activates this call.
                println("[CN CALL][CALL ANSWER RECEIVED] call_id=$callId")
                sendCallAction(ACTION_CALL_ACCEPT, callId, peerId)
            }

            override fun onReject() {
                println("[CN CALL][CALL TERMINAL] rejected call_id=$callId")
                sendCallAction(ACTION_CALL_REJECT, callId, peerId)
                finish(DisconnectCause.REJECTED)
            }

            override fun onAbort() {
                sendCallAction(ACTION_CALL_DISCONNECT, callId, peerId)
                finish(DisconnectCause.LOCAL)
            }

            override fun onDisconnect() {
                println("[CN CALL][CALL TERMINAL] disconnected call_id=$callId")
                sendCallAction(ACTION_CALL_DISCONNECT, callId, peerId)
                finish(DisconnectCause.LOCAL)
            }

            override fun onMuteStateChanged(isMuted: Boolean) {
                super.onMuteStateChanged(isMuted)
                sendMuteChanged(callId, isMuted)
            }

            @Suppress("DEPRECATION")
            override fun onCallAudioStateChanged(state: CallAudioState) {
                super.onCallAudioStateChanged(state)
                sendMuteChanged(callId, state.isMuted)
            }

            private fun finish(cause: Int) {
                if (connections.remove(callId) != null) {
                    peers.remove(callId)
                    setRingbackRequested(false)
                    setDisconnected(DisconnectCause(cause))
                    destroy()
                    stopForegroundIfIdle(applicationContext)
                }
            }
        }

        connections[callId] = connection
        peers[callId] = peerId
        connection.setAudioModeIsVoip(true)
        connection.connectionCapabilities = Connection.CAPABILITY_MUTE
        connection.setAddress(address, TelecomManager.PRESENTATION_ALLOWED)
        connection.setCallerDisplayName(displayName, TelecomManager.PRESENTATION_ALLOWED)
        return connection
    }

    private fun sendCallAction(action: String, callId: String, peerId: String) {
        sendBroadcast(Intent(this, TelecomCallActionReceiver::class.java).apply {
            this.action = action
            putExtra(EXTRA_CALL_ID, callId)
            putExtra(EXTRA_CALLER_ID, peerId)
        })
    }

    private fun sendMuteChanged(callId: String, isMuted: Boolean) {
        sendBroadcast(Intent(this, TelecomCallActionReceiver::class.java).apply {
            action = ACTION_CALL_MUTE_CHANGED
            putExtra(EXTRA_CALL_ID, callId)
            putExtra(TelecomCallActionReceiver.EXTRA_IS_MUTED, isMuted)
        })
    }
}

package com.example.mobile

import android.content.ComponentName
import android.content.Context
import android.content.pm.PackageManager
import android.os.Build
import android.net.Uri
import android.os.Bundle
import android.telecom.PhoneAccount
import android.telecom.PhoneAccountHandle
import android.telecom.TelecomManager

object TelecomHelper {

    private const val ACCOUNT_ID = "cn_call"

    fun register(context: Context) {
        val telecomManager =
            context.getSystemService(Context.TELECOM_SERVICE) as TelecomManager

        val component = ComponentName(
            context,
            CallConnectionService::class.java
        )

        val handle = PhoneAccountHandle(
            component,
            ACCOUNT_ID
        )

        val account = PhoneAccount.builder(
            handle,
            "CN CALL"
        )
            .setCapabilities(
                PhoneAccount.CAPABILITY_CALL_PROVIDER
            )
            .addSupportedUriScheme("tel")
            .build()

        telecomManager.registerPhoneAccount(account)
    }

    fun isEnabled(context: Context): Boolean {
        if (!hasPhoneAccountPermission(context)) return false
        val telecomManager =
            context.getSystemService(Context.TELECOM_SERVICE) as TelecomManager
        return try {
            telecomManager.getPhoneAccount(getHandle(context))?.isEnabled == true
        } catch (error: SecurityException) {
            println("CN CALL Telecom: PhoneAccount access denied: $error")
            false
        }
    }

    /**
     * Reports a network call to the system-managed Telecom stack.  Registration
     * alone is not sufficient: managed accounts must be enabled by the user in
     * the Phone app before Telecom is permitted to bind the ConnectionService.
     */
    fun addIncomingCall(
        context: Context,
        callerId: String,
        callerName: String,
        callId: String,
    ): Boolean {
        if (callId.isBlank() || callerId.isBlank()) return false
        if (!hasPhoneAccountPermission(context)) {
            println("CN CALL Telecom: READ_PHONE_NUMBERS is not granted")
            return false
        }
        register(context)

        val telecomManager =
            context.getSystemService(Context.TELECOM_SERVICE) as TelecomManager

        val handle = getHandle(context)

        val account = try {
            telecomManager.getPhoneAccount(handle)
        } catch (error: SecurityException) {
            println("CN CALL Telecom: PhoneAccount access denied: $error")
            return false
        }
        if (account?.isEnabled != true) {
            println("CN CALL Telecom: PhoneAccount is not enabled by the user")
            return false
        }

        if (!telecomManager.isIncomingCallPermitted(handle)) {
            println("CN CALL Telecom: incoming call is not permitted")
            return false
        }

        val extras = Bundle().apply {
            putParcelable(
                TelecomManager.EXTRA_INCOMING_CALL_ADDRESS,
                Uri.fromParts("tel", callerId, null)
            )
            putString(CallConnectionService.EXTRA_CALL_ID, callId)
            putString(CallConnectionService.EXTRA_CALLER_ID, callerId)
            putString(CallConnectionService.EXTRA_CALLER_NAME, callerName)
        }

        return try {
            telecomManager.addNewIncomingCall(handle, extras)
            true
        } catch (error: SecurityException) {
            println("CN CALL Telecom: incoming call permission denied: $error")
            false
        }
    }

    fun getHandle(context: Context): PhoneAccountHandle {
        val component = ComponentName(
            context,
            CallConnectionService::class.java
        )

        return PhoneAccountHandle(
            component,
            ACCOUNT_ID
        )
    }

    fun hasPhoneAccountPermission(context: Context): Boolean =
        Build.VERSION.SDK_INT < Build.VERSION_CODES.O ||
            context.checkSelfPermission(android.Manifest.permission.READ_PHONE_NUMBERS) ==
                PackageManager.PERMISSION_GRANTED
}

package com.example.mobile

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.embedding.engine.FlutterEngineCache
import io.flutter.embedding.engine.dart.DartExecutor
import io.flutter.plugin.common.MethodChannel
import io.flutter.plugins.GeneratedPluginRegistrant
import org.json.JSONArray
import org.json.JSONObject

/** Bridges commands from the system InCall UI to the one Flutter/LiveKit path. */
class TelecomCallActionReceiver : BroadcastReceiver() {
    companion object {
        private const val ENGINE_ID = "cn_call_telecom_background_engine"
        const val EXTRA_IS_MUTED = "is_muted"
        private const val EVENTS_CHANNEL = "cn_call/telecom_events"
        private const val ACTION_QUEUE_KEY = "flutter.cn_call_telecom_actions_v1"
        private const val CALL_CHANNEL = "cn_call/call"
    }

    override fun onReceive(context: Context, intent: Intent?) {
        val event = intent ?: return
        val action = when (event.action) {
            CallConnectionService.ACTION_CALL_ACCEPT -> "accept"
            CallConnectionService.ACTION_CALL_REJECT -> "reject"
            CallConnectionService.ACTION_CALL_DISCONNECT -> "ended"
            CallConnectionService.ACTION_CALL_OUTGOING -> "outgoing"
            CallConnectionService.ACTION_CALL_MUTE_CHANGED -> "mute"
            else -> return
        }
        val callId = event.getStringExtra(CallConnectionService.EXTRA_CALL_ID).orEmpty().trim()
        val peerId = event.getStringExtra(CallConnectionService.EXTRA_CALLER_ID).orEmpty().trim()
        if (callId.isEmpty() || (action != "mute" && peerId.isEmpty())) {
            println("CN CALL Telecom: ignored $action without call identity")
            return
        }

        val prefs = context.getSharedPreferences("FlutterSharedPreferences", Context.MODE_PRIVATE)
        // Mute is an independent Telecom callback.  It must never overwrite a
        // pending accept/outgoing/reject/end action while a cold Dart engine is
        // starting, otherwise the call would reach InCallUI without LiveKit.
        if (action == "mute") {
            prefs.edit()
                .putString("flutter.cn_call_telecom_mute_call_id", callId)
                .putBoolean("flutter.cn_call_telecom_is_muted", event.getBooleanExtra(EXTRA_IS_MUTED, false))
                .apply()
            dispatchMuteToFlutter(context, callId, event.getBooleanExtra(EXTRA_IS_MUTED, false))
            return
        }

        enqueueAction(prefs, action, callId, peerId)
        println("[CN CALL][CALL ACTION QUEUED] action=$action call_id=$callId")

        when (action) {
            "accept", "outgoing" -> {
                // Incoming ACCEPT may need the foreground service immediately
                // after the user answers from Samsung InCallUI. Outgoing calls
                // stay in Telecom DIALING while the app-managed ringback plays;
                // the phone-call FGS is started later when Telecom becomes ACTIVE.
                if (action == "accept") {
                    CallForegroundService.start(context, callId, peerId, "CN CALL")
                }

                val existingEngine = FlutterEngineCache.getInstance().get(ENGINE_ID)
                startBackgroundFlutter(context)
                existingEngine?.let { dispatchActionToFlutter(it, action, callId, peerId) }
            }
            "reject", "ended" -> {
                CallForegroundService.stop(context)
                val existingEngine = FlutterEngineCache.getInstance().get(ENGINE_ID)
                startBackgroundFlutter(context)
                existingEngine?.let { dispatchActionToFlutter(it, action, callId, peerId) }
            }
        }
    }

    private fun startBackgroundFlutter(context: Context) {
        val cache = FlutterEngineCache.getInstance()
        if (cache.get(ENGINE_ID) != null) return
        val engine = FlutterEngine(context.applicationContext)
        GeneratedPluginRegistrant.registerWith(engine)
        installNativeCallChannel(engine)
        cache.put(ENGINE_ID, engine)
        engine.dartExecutor.executeDartEntrypoint(
            DartExecutor.DartEntrypoint("flutter_assets", "package:mobile/main.dart", "telecomBackgroundMain")
        )
        println("CN CALL Telecom: headless Flutter engine started")
    }

    /** The cached headless engine is not MainActivity's engine.  It therefore
     * needs the same native call channel, otherwise cleanup/activation throws
     * MissingPluginException after Telecom ANSWERED. */
    private fun installNativeCallChannel(engine: FlutterEngine) {
        MethodChannel(engine.dartExecutor.binaryMessenger, CALL_CHANNEL)
            .setMethodCallHandler { call, result ->
                val callId = call.argument<String>("callId").orEmpty().trim()
                when (call.method) {
                    "disconnectTelecomCall" -> {
                        CallConnectionService.disconnectCall(callId, notifyFlutter = false)
                        result.success(true)
                    }
                    "activateTelecomCall" -> result.success(CallConnectionService.activateCall(callId))
                    "failTelecomCall" -> result.success(CallConnectionService.failCall(callId))
                    else -> result.notImplemented()
                }
            }
    }

    private fun enqueueAction(
        prefs: android.content.SharedPreferences,
        action: String,
        callId: String,
        peerId: String,
    ) {
        val queue = try { JSONArray(prefs.getString(ACTION_QUEUE_KEY, "[]")) } catch (_: Exception) { JSONArray() }
        // A repeated Telecom callback must not produce a second accept/reject.
        for (index in 0 until queue.length()) {
            val existing = queue.optJSONObject(index) ?: continue
            if (existing.optString("action") == action && existing.optString("callId") == callId) return
        }
        queue.put(JSONObject().apply {
            put("action", action)
            put("callId", callId)
            put("peerId", peerId)
        })
        prefs.edit().putString(ACTION_QUEUE_KEY, queue.toString()).apply()
    }

    private fun dispatchMuteToFlutter(context: Context, callId: String, isMuted: Boolean) {
        val engine = FlutterEngineCache.getInstance().get(ENGINE_ID)
        if (engine == null) {
            startBackgroundFlutter(context)
            return
        }
        MethodChannel(engine.dartExecutor.binaryMessenger, EVENTS_CHANNEL)
            .invokeMethod("muteChanged", mapOf("callId" to callId, "isMuted" to isMuted))
    }

    private fun dispatchActionToFlutter(
        engine: FlutterEngine,
        action: String,
        callId: String,
        peerId: String
    ) {
        MethodChannel(engine.dartExecutor.binaryMessenger, EVENTS_CHANNEL).invokeMethod(
            "callAction",
            mapOf("action" to action, "callId" to callId, "peerId" to peerId)
        )
    }
}

package com.example.mobile

import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.Service
import android.content.Context
import android.content.Intent
import android.content.pm.ServiceInfo
import android.os.Build
import android.os.IBinder

class CallForegroundService : Service() {

    companion object {
        private const val CHANNEL_ID = "cn_call_ongoing_call"
        private const val NOTIFICATION_ID = 24001

        fun start(
            context: Context,
            callId: String,
            callerId: String,
            callerName: String,
        ) {
            val intent = Intent(
                context.applicationContext,
                CallForegroundService::class.java
            ).apply {
                putExtra("call_id", callId)
                putExtra("caller_id", callerId)
                putExtra("caller_name", callerName)
            }

            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                context.applicationContext.startForegroundService(intent)
            } else {
                context.applicationContext.startService(intent)
            }
        }

        fun stop(context: Context) {
            context.applicationContext.stopService(
                Intent(
                    context.applicationContext,
                    CallForegroundService::class.java
                )
            )
        }
    }

    override fun onCreate() {
        super.onCreate()

        createChannel()
    }

    override fun onStartCommand(
        intent: Intent?,
        flags: Int,
        startId: Int
    ): Int {

        val callId =
            intent?.getStringExtra("call_id")
                ?.trim()
                .orEmpty()

        val callerName =
            intent?.getStringExtra("caller_name")
                ?: "CN CALL"

        val callerId =
            intent?.getStringExtra("caller_id")
                ?: ""

        if (callId.isEmpty()) {
            println("CN CALL Telecom: refusing foreground service without callId")
            stopSelf(startId)
            return START_NOT_STICKY
        }

        val notification =
            Notification.Builder(
                this,
                CHANNEL_ID
            )
                .setSmallIcon(
                    android.R.drawable.sym_call_incoming
                )
                .setCategory(
                    Notification.CATEGORY_CALL
                )
                .setVisibility(
                    Notification.VISIBILITY_PUBLIC
                )
                .setContentTitle("CN CALL")
                .setContentText("Call in progress with ${callerId.ifEmpty { callerName }}")
                // Samsung InCallUI is the sole call UI.  This notification only
                // keeps the process eligible to run while the Telecom call is active.
                .setOngoing(true)
                .setAutoCancel(false)
                .build()

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            startForeground(
                NOTIFICATION_ID,
                notification,
                ServiceInfo.FOREGROUND_SERVICE_TYPE_PHONE_CALL
            )
        } else {
            startForeground(
                NOTIFICATION_ID,
                notification
            )
        }

        println("CN CALL Telecom: phoneCall foreground service active")

        return START_NOT_STICKY
    }

    override fun onBind(intent: Intent?): IBinder? {
        return null
    }

    private fun createChannel() {

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {

            val channel = NotificationChannel(
                CHANNEL_ID,
                "Incoming Calls",
                NotificationManager.IMPORTANCE_HIGH
            )

            channel.description =
                "CN CALL incoming calls"

            val manager =
                getSystemService(
                    NotificationManager::class.java
                )

            manager.createNotificationChannel(channel)
        }
    }
}

package com.example.mobile

import org.json.JSONArray
import org.json.JSONObject
import com.google.firebase.messaging.FirebaseMessagingService
import com.google.firebase.messaging.RemoteMessage

class CallFirebaseService : FirebaseMessagingService() {

    override fun onMessageReceived(message: RemoteMessage) {

        val type = message.data["type"]

            if (type == "call_cancelled" || type == "call_reject" || type == "hangup" || type == "timeout" || type == "disconnected") {
                val callId = message.data["call_id"] ?: return

                CallConnectionService.disconnectCall(callId)

                markCallEnded(callId)

                println(
                    "CN CALL Telecom: FCM terminal event handled " +
                        "type=$type callId=$callId"
                )

                return
            }

        if (type != "incoming_call") {
            return
        }

        val callerName =
            message.data["caller_name"]
                ?: "CN CALL"

        val callerId =
            message.data["caller_id"]
                ?: message.data["from_id"]
                ?: ""

        if (callerId.isEmpty()) {
            return
        }

        val callId = message.data["call_id"]?.trim().orEmpty()
        if (callId.isEmpty()) return
        if (isCallEnded(callId)) {
            println("CN CALL: ignored stale incoming FCM. callId=$callId")
            return
        }

        // System-managed ConnectionService is the only incoming-call path.
        try {
            val submitted = TelecomHelper.addIncomingCall(
                context = this,
                callerId = callerId,
                callerName = callerName,
                callId = callId,
            )

            if (submitted) {
                // Keep native FCM and Flutter on the same per-call guard. This
                // prevents a second incoming call from replacing the Samsung
                // InCallUI call while Flutter is terminated.
                getSharedPreferences("FlutterSharedPreferences", MODE_PRIVATE)
                    .edit()
                    .putString("flutter.cn_call_active_call_id", callId)
                    .putLong("flutter.cn_call_active_call_at", System.currentTimeMillis())
                    .apply()
            }

            println("[CN CALL][CALL UI RINGING] submitted=$submitted call_id=$callId callerId=$callerId")
            return
        } catch (e: Exception) {
            println(
                "CN CALL Telecom: incoming call failed. " +
                    "error=$e"
            )
        }
    }

    private fun isCallEnded(callId: String): Boolean {
        val prefs = getSharedPreferences("FlutterSharedPreferences", MODE_PRIVATE)
        return endedCallIds(prefs).contains(callId)
    }

    private fun markCallEnded(callId: String) {
        val prefs = getSharedPreferences("FlutterSharedPreferences", MODE_PRIVATE)
        val endedIds = endedCallIds(prefs).toMutableList()
        endedIds.remove(callId)
        endedIds.add(callId)
        if (endedIds.size > 32) {
            endedIds.subList(0, endedIds.size - 32).clear()
        }

        val editor = prefs.edit().putString(
            "flutter.cn_call_ended_call_ids_v2",
            JSONArray(endedIds).toString()
        )
        val pending = prefs.getString("flutter.pending_incoming_call", null)
        val pendingId = try {
            JSONObject(pending ?: "{}").optString("call_id")
        } catch (_: Exception) {
            ""
        }
        if (pendingId == callId) {
            editor.remove("flutter.pending_incoming_call")
        }
        if (prefs.getString("flutter.cn_call_active_call_id", null) == callId) {
            editor.remove("flutter.cn_call_active_call_id")
            editor.remove("flutter.cn_call_active_call_at")
        }
        editor.apply()
    }

    private fun endedCallIds(prefs: android.content.SharedPreferences): List<String> {
        val encoded = prefs.getString("flutter.cn_call_ended_call_ids_v2", "[]")
        return try {
            val values = JSONArray(encoded ?: "[]")
            List(values.length()) { index -> values.optString(index).trim() }
                .filter { it.isNotEmpty() }
        } catch (_: Exception) {
            emptyList()
        }
    }
}

package com.example.mobile

import android.content.Intent
import android.content.pm.PackageManager
import android.net.Uri
import android.os.Bundle
import android.os.Build
import android.telecom.TelecomManager
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.embedding.engine.FlutterEngineCache
import io.flutter.plugin.common.MethodChannel

class MainActivity : FlutterActivity() {
    private val channel = "cn_call/call"
    private val readPhoneNumbersRequestCode = 9000
    private val callPhoneRequestCode = 9001
    private var pendingOutgoingTarget: String? = null
    private var pendingOutgoingResult: MethodChannel.Result? = null

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        // Registration does not enable a managed account; the user does that
        // in Phone accounts settings before Telecom can bind this service.
        TelecomHelper.register(this)
    }

    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        // Telecom actions must target this already-running Flutter isolate.
        // Without this cache entry the receiver starts a second isolate, which
        // logs in again and creates a competing WebSocket for the same user.
        FlutterEngineCache.getInstance().put("cn_call_telecom_background_engine", flutterEngine)
        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, channel)
            .setMethodCallHandler { call, result ->
                when (call.method) {
                    "openTelecomSettings" -> {
                        startActivity(Intent(TelecomManager.ACTION_CHANGE_PHONE_ACCOUNTS))
                        result.success(true)
                    }
                    "isTelecomAccountEnabled" -> result.success(TelecomHelper.isEnabled(this))
                    "addIncomingTelecomCall" -> {
                        val callId = call.argument<String>("callId").orEmpty().trim()
                        val callerId = call.argument<String>("callerId").orEmpty().trim()
                        val callerName = call.argument<String>("callerName").orEmpty().trim()
                        result.success(
                            try {
                                TelecomHelper.addIncomingCall(
                                    this, callerId, callerName.ifEmpty { "CN CALL" }, callId
                                )
                            } catch (error: SecurityException) {
                                println("CN CALL Telecom: managed account is unavailable: $error")
                                false
                            }
                        )
                    }
                    "placeOutgoingTelecomCall" -> {
                        val targetId = call.argument<String>("targetId").orEmpty().trim()
                        if (targetId.isEmpty()) {
                            result.success(false)
                        } else if (hasPhoneAccountPermission() && hasCallPhonePermission()) {
                            result.success(placeOutgoingTelecomCall(targetId))
                        } else {
                            pendingOutgoingTarget = targetId
                            pendingOutgoingResult = result
                            requestPhoneNumbersPermissionOrFail()
                        }
                    }
                    "disconnectTelecomCall" -> {
                        val callId = call.argument<String>("callId").orEmpty().trim()
                        if (callId.isEmpty()) result.success(false)
                        else {
                            CallConnectionService.disconnectCall(callId, notifyFlutter = false)
                            result.success(true)
                        }
                    }
                    "activateTelecomCall" -> {
                        result.success(CallConnectionService.activateCall(
                            call.argument<String>("callId").orEmpty().trim()
                        ))
                    }
                    "failTelecomCall" -> {
                        result.success(CallConnectionService.failCall(
                            call.argument<String>("callId").orEmpty().trim()
                        ))
                    }
                    else -> result.notImplemented()
                }
            }
    }

    override fun onRequestPermissionsResult(
        requestCode: Int,
        permissions: Array<out String>,
        grantResults: IntArray
    ) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults)
        if (requestCode == readPhoneNumbersRequestCode) {
            if (hasPhoneAccountPermission()) {
                if (hasCallPhonePermission()) finishPendingOutgoing()
                else requestPermissions(arrayOf(android.Manifest.permission.CALL_PHONE), callPhoneRequestCode)
            } else {
                finishPendingOutgoing()
            }
            return
        }
        if (requestCode != callPhoneRequestCode) return
        finishPendingOutgoing()
    }

    private fun finishPendingOutgoing() {
        val targetId = pendingOutgoingTarget
        val result = pendingOutgoingResult
        pendingOutgoingTarget = null
        pendingOutgoingResult = null
        result?.success(targetId != null && hasPhoneAccountPermission() && hasCallPhonePermission() && placeOutgoingTelecomCall(targetId))
    }

    private fun hasCallPhonePermission(): Boolean =
        Build.VERSION.SDK_INT < Build.VERSION_CODES.M ||
            checkSelfPermission(android.Manifest.permission.CALL_PHONE) == PackageManager.PERMISSION_GRANTED

    private fun hasPhoneAccountPermission(): Boolean = TelecomHelper.hasPhoneAccountPermission(this)

    private fun requestPhoneNumbersPermissionOrFail() {
        if (hasPhoneAccountPermission()) {
            requestPermissions(arrayOf(android.Manifest.permission.CALL_PHONE), callPhoneRequestCode)
            return
        }
        val prefs = getSharedPreferences("cn_call_permissions", MODE_PRIVATE)
        if (prefs.getBoolean("read_phone_numbers_requested", false)) {
            finishPendingOutgoing()
            return
        }
        prefs.edit().putBoolean("read_phone_numbers_requested", true).apply()
        requestPermissions(arrayOf(android.Manifest.permission.READ_PHONE_NUMBERS), readPhoneNumbersRequestCode)
    }

    private fun placeOutgoingTelecomCall(targetId: String): Boolean {
        TelecomHelper.register(this)
        if (!hasPhoneAccountPermission()) return false
        val manager = getSystemService(TELECOM_SERVICE) as TelecomManager
        val account = TelecomHelper.getHandle(this)
        val enabled = try { manager.getPhoneAccount(account)?.isEnabled == true } catch (_: SecurityException) { false }
        if (!enabled || !manager.isOutgoingCallPermitted(account)) {
            println("CN CALL Telecom: managed account unavailable for outgoing call")
            return false
        }
        return try {
            manager.placeCall(Uri.fromParts("tel", targetId, null), Bundle().apply {
                putParcelable(TelecomManager.EXTRA_PHONE_ACCOUNT_HANDLE, account)
            })
            true
        } catch (error: SecurityException) {
            println("CN CALL Telecom: unable to place managed call: $error")
            false
        }
    }
}

